-- ── §1 Table ──────────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE public.brand_items (
  id                uuid PRIMARY KEY,
  brand_key         text NOT NULL CHECK (brand_key ~ '^[a-z0-9_]+$'),
  brand             text NOT NULL,
  country           text NOT NULL CHECK (country ~ '^[A-Z]{2}$'),
  region            text NOT NULL CHECK (region ~ '^[A-Z]{2}(-[A-Z]{2,3})?$'),
  is_default_region boolean NOT NULL,
  item              text NOT NULL,
  item_norm         text NOT NULL,
  variant           text,
  variant_norm      text NOT NULL,
  serving_desc      text,
  serving_g         numeric CHECK (serving_g > 0),
  serving_ml        numeric CHECK (serving_ml > 0),
  basis             text NOT NULL CHECK (basis IN ('per_serving','per_100g','per_100ml')),
  amount_rule       text NOT NULL CHECK (amount_rule IN ('serving','stated_or_portion','stated_only')),
  kcal              numeric NOT NULL CHECK (kcal >= 0),
  protein_g         numeric CHECK (protein_g >= 0),
  carbs_g           numeric CHECK (carbs_g >= 0),
  fat_g             numeric CHECK (fat_g >= 0),
  fiber_g           numeric CHECK (fiber_g >= 0),
  sugar_g           numeric CHECK (sugar_g >= 0),
  sugar_lt_g        numeric CHECK (sugar_lt_g > 0),
  sodium_mg         numeric CHECK (sodium_mg >= 0),
  atwater_kcal      numeric GENERATED ALWAYS AS (4 * protein_g + 4 * carbs_g + 9 * fat_g) STORED,
  atwater_ok        boolean,
  veg               text CHECK (veg IN ('veg','nonveg','vegan','egg')),
  is_default_size   boolean NOT NULL,
  status            text NOT NULL CHECK (status IN ('verified','held','unserved')),
  status_reason     text,
  qa_severity       text NOT NULL CHECK (qa_severity IN ('clean','caveat','conflict','error')),
  qa_codes          text[] NOT NULL,
  qa_flag           text,
  gate_codes        text[] NOT NULL,
  source_url        text NOT NULL CHECK (source_url ~ '^https://'),
  source_title      text NOT NULL,
  source_version    text NOT NULL,
  source_date       date NOT NULL,
  source_date_basis text NOT NULL CHECK (source_date_basis IN ('document','retrieved')),
  page              text,
  notes             text,
  brand_slug        text NOT NULL,
  source_row        integer NOT NULL CHECK (source_row > 1),
  UNIQUE (brand_slug, source_row),
  CHECK ((basis = 'per_serving') = (amount_rule = 'serving')),
  CHECK ((atwater_ok IS NULL) = (atwater_kcal IS NULL)),
  CHECK (sugar_g IS NULL OR sugar_lt_g IS NULL),
  CHECK (status <> 'verified' OR (atwater_ok AND qa_severity <> 'error' AND cardinality(gate_codes) = 0)),
  CHECK (status <> 'verified' OR qa_severity <> 'conflict' OR status_reason LIKE 'decision:% released the conflict'),
  CHECK (status = 'verified' OR status_reason IS NOT NULL),
  CHECK (NOT is_default_size OR status = 'verified')
);
COMMENT ON TABLE public.brand_items IS 'v1.2 WP10. Official chain-menu nutrition, per serving exactly as the brand printed it, with source and QA. '
  'Written only by migrations (scripts/import-brands.ts); authenticated users read served (verified) rows, service_role reads every row, nobody writes through the API. '
  'Not a food_items source: no name keys, invisible to fts and search_foods. Only the brand tier reads it, behind RESOLVER_BRAND (off by default). '
  'held = QA error, QA conflict or a failed gate, awaiting review; unserved = usable numbers withheld by a founder rule. '
  'A row of any status means "we hold this item" (WP11 web lookup: missing = no row at all).';
COMMENT ON COLUMN public.brand_items.basis IS 'per_serving: the numbers are for one serving as serving_desc describes; serving_g / serving_ml only when printed (never derived; ml is never treated as grams). per_100g / per_100ml: the numbers are per 100 g / 100 ml, and serving_g / serving_ml = 100 is that reference amount, not a portion.';
COMMENT ON COLUMN public.brand_items.amount_rule IS 'serving: count x the serving. stated_or_portion: per-100 numbers scaled by an amount in the basis unit (grams for per_100g, millilitres for per_100ml), stated by the user or from the portion engine; a per_100ml row is never scaled by a gram amount (no density is assumed). stated_only: per-100 numbers with no published portion, served only when the user states an amount in the basis unit (decisions.json per100_no_portion).';
COMMENT ON COLUMN public.brand_items.atwater_ok IS 'Atwater gate (decisions.json atwater_rule): |kcal - (4P+4C+9F)| within pct% of kcal or within kcal_slack kcal. NULL = P, C or F not published.';
COMMENT ON COLUMN public.brand_items.is_default_size IS 'The serving used when the user names the item without a size (decisions.json default_size); at most one per (brand_key, region, item_norm, veg).';
COMMENT ON COLUMN public.brand_items.is_default_region IS 'Tie-break when the same item is published for several regions (McDonald''s franchisees, Behrouz cities); decisions.json.';
COMMENT ON COLUMN public.brand_items.sugar_lt_g IS 'The brand printed an upper bound ("<2.0" g); sugar_g is then NULL.';
COMMENT ON COLUMN public.brand_items.source_date IS 'The document''s own date where it prints one (source_date_basis document), else the date it was read (retrieved). source_version is the text as recorded.';
CREATE INDEX brand_items_lookup_idx ON public.brand_items (brand_key, item_norm) WHERE status = 'verified';

-- ── §2 Privileges (052 pattern: live default privileges hand anon/authenticated everything on new tables) ──
ALTER TABLE public.brand_items ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.brand_items FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.brand_items TO authenticated, service_role;                -- writes: migrations only
CREATE POLICY "Authenticated users read served brand items" ON public.brand_items
  FOR SELECT TO authenticated USING (status = 'verified');

