-- ── §4 Self-checks: any failure aborts the whole file ──────────────────────────────────────────────────────
DO $check$
DECLARE n bigint; t text;
BEGIN
  SELECT count(*) INTO n FROM public.brand_items;
  IF n <> 3741 THEN RAISE EXCEPTION 'brand_items: % rows, expected 3741', n; END IF;
  SELECT string_agg(brand_slug || ':' || status || ':' || c, ',' ORDER BY brand_slug COLLATE "C", status COLLATE "C") INTO t
    FROM (SELECT brand_slug, status, count(*) AS c FROM public.brand_items GROUP BY brand_slug, status) s;
  IF t IS DISTINCT FROM 'amul:held:1,amul:unserved:1,amul:verified:64,barista:unserved:2,behrouz_biryani:held:51,behrouz_biryani:verified:59,blue_tokai:held:8,blue_tokai:unserved:7,blue_tokai:verified:143,burger_king_india:held:12,burger_king_india:verified:99,cafe_coffee_day:unserved:98,dominos:held:69,dominos:verified:408,faasos:held:1,faasos:verified:92,haldirams:unserved:1,haldirams:verified:28,kfc_india:held:43,kfc_india:verified:189,lapinoz_pizza:unserved:2,lapinoz_pizza:verified:197,mcdonalds_india_north_east:held:5,mcdonalds_india_north_east:unserved:12,mcdonalds_india_north_east:verified:104,mcdonalds_india_west_south:held:6,mcdonalds_india_west_south:verified:186,naturals_ice_cream:held:42,naturals_ice_cream:unserved:1,naturals_ice_cream:verified:107,pizza_hut:held:12,pizza_hut:unserved:7,pizza_hut:verified:295,starbucks_india:held:83,starbucks_india:unserved:1,starbucks_india:verified:892,subway_india:held:6,subway_india:verified:180,taco_bell_india:verified:105,theobroma:unserved:1,theobroma:verified:113,wow_momo:unserved:8' THEN
    RAISE EXCEPTION 'brand_items: per-brand status counts differ from the manifest: %', t;
  END IF;
  -- the Atwater rule, recomputed in exact numeric arithmetic, agrees with the generator on every row
  SELECT count(*) INTO n FROM public.brand_items WHERE atwater_ok IS DISTINCT FROM (CASE
    WHEN atwater_kcal IS NULL THEN NULL
    WHEN kcal > 0 THEN NOT (100 * abs(kcal - atwater_kcal) > 15 * kcal AND abs(kcal - atwater_kcal) > 15)
    ELSE NOT (atwater_kcal > 15) END);
  IF n > 0 THEN RAISE EXCEPTION 'brand_items: % rows disagree with the Atwater rule', n; END IF;
  -- served rows: sugar never above carbs (2% + 0.5 g tolerance)
  SELECT count(*) INTO n FROM public.brand_items WHERE status = 'verified' AND 100 * sugar_g > 102 * carbs_g + 50;
  IF n > 0 THEN RAISE EXCEPTION 'brand_items: % served rows have more sugar than carbs', n; END IF;
  -- at most one default size per item group
  SELECT count(*) INTO n FROM (SELECT 1 FROM public.brand_items WHERE is_default_size
    GROUP BY brand_key, region, item_norm, coalesce(veg, '') HAVING count(*) > 1) s;
  IF n > 0 THEN RAISE EXCEPTION 'brand_items: % item groups have two default sizes', n; END IF;
  -- privileges and RLS
  IF pg_catalog.has_table_privilege('anon', 'public.brand_items', 'SELECT')
     OR NOT pg_catalog.has_table_privilege('authenticated', 'public.brand_items', 'SELECT')
     OR NOT pg_catalog.has_table_privilege('service_role', 'public.brand_items', 'SELECT')
     OR pg_catalog.has_table_privilege('authenticated', 'public.brand_items', 'INSERT, UPDATE, DELETE, TRUNCATE')
     OR pg_catalog.has_table_privilege('service_role', 'public.brand_items', 'INSERT, UPDATE, DELETE, TRUNCATE') THEN
    RAISE EXCEPTION 'brand_items: privileges are not read-only (anon none, authenticated and service_role SELECT only)';
  END IF;
  IF NOT (SELECT relrowsecurity FROM pg_catalog.pg_class WHERE oid = 'public.brand_items'::regclass) THEN
    RAISE EXCEPTION 'brand_items: row level security is off';
  END IF;
  RAISE NOTICE 'brand_items: 3741 rows (3261 verified, 339 held, 141 unserved); self-checks passed';
END
$check$;
